ST.xhtml:p:
Cylinder1UpTrigger(CLK := g_biLoadCylinder1Up);
Cylinder1Close(CLK := g_biLoadCylinder1Close);
R_Trigger1(CLK := g_bPlcStartBuffer);
R_Trigger2(CLK := g_biLoadZeroOpen);

IF Cylinder1UpTrigger.Q THEN
  g_boLoadCylinder1Done := FALSE;
  nCylinderState := 1;
  bCheckFirst := FALSE;
END_IF;
IF Cylinder1Close.Q THEN
  g_boLoadCylinder1Done := FALSE;
  nCylinderState := 0;
END_IF;

IF R_Trigger2.Q THEN
  nLZeroState := 1;
END_IF;

CASE nCylinderState OF
  0:
    nCylinderState := 0;
  1:
    g_boLoadCylinder1 := TRUE;
    g_boLoadCylinder2 := TRUE;
    CylinderDelay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinderDelay)));
    IF CylinderDelay.Q THEN
      CylinderDelay(IN := FALSE);
      nCylinderState := 2;
    END_IF;
  2:
    IF g_bLengthCheck4 THEN
      g_boLoadCylinder1Done := TRUE;
      nCylinderState := 0;
    ELSE
      nCylinderState := 3;
    END_IF;
  3:
    IF bCheckFirst THEN
      nCylinderState := 20;
      g_boLoadCylinder1 := FALSE;
      g_boLoadCylinder2 := FALSE;
      g_bNoPipeWarn := TRUE;
    ELSE
      g_boLoadCylinder1 := FALSE;
      g_boLoadCylinder2 := FALSE;
      CylinderDelay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinderDelay)));
      IF CylinderDelay.Q THEN
        CylinderDelay(IN := FALSE);
        nCylinderState := 4;
        bCheckFirst := TRUE;
      END_IF;
    END_IF;
  4:
    g_boLoadCylinder1Up := TRUE;
    Cylinder1Delay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinder1Delay)));
    IF Cylinder1Delay.Q THEN
      g_boLoadCylinder1Up := FALSE;
      Cylinder1Delay(IN := FALSE);
      nCylinderState := 1;
    END_IF;   
  20:
    IF R_Trigger1.Q THEN
      nCylinderState := 4;
    END_IF;
END_CASE;

CASE nLZeroState OF
  0:
    nLZeroState := 0;
  1:
    g_boLoadCylinder3Up := TRUE;
    Cylinder3Delay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinder1Delay)));
    IF Cylinder3Delay.Q THEN
      g_boLoadCylinder3Up := FALSE;
      Cylinder3Delay(IN := FALSE);
      nLZeroState := 2;
    END_IF;
  2:
    g_boLoadCylinder3Up := FALSE;
    Cylinder3Delay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinder1Delay)));
    IF Cylinder3Delay.Q THEN
      g_boLoadCylinder3Up := FALSE;
      Cylinder3Delay(IN := FALSE);
      nLZeroState := 0;
    END_IF;
END_CASE;

(*上料气缸2，做循环上下顶升*)
Cylinder2AutoUpDelay(IN := NOT Cylinder2AutoUpDelay.Q, PT := LREAL_TO_TIME(FUN_MStoS(nCylinder2AutoUpDelay)));
IF Cylinder2AutoUpDelay.Q THEN
    Cylinder2AutoUpDelay(IN := FALSE);
    g_boLoadCylinder2Up := TRUE;
END_IF;

Cylinder2AutoDownDelay(IN := g_boLoadCylinder2Up, PT := LREAL_TO_TIME(FUN_MStoS(nCylinder2AutoDownDelay)));
IF Cylinder2AutoDownDelay.Q THEN
    g_boLoadCylinder2Up := FALSE;
END_IF;

IF g_bPlcResetBuffer THEN
  Cylinder2AutoUpDelay(IN := FALSE);
  Cylinder2AutoDownDelay(IN := FALSE);
  Cylinder1Delay(IN := FALSE);
  CylinderDelay(IN := FALSE);
  g_boLoadCylinder1Up := FALSE;
  nCylinderState := 0;
END_IF;
